  class Service : public ::grpc::Service {
   public:
    Service();
    virtual ~Service();
    // 全球账号角色目录；只接受已签名的 login 调用，不使用 Redis 归属降级。
    virtual ::grpc::Status ReadAccountDirectory(::grpc::ServerContext* context, const ::data_service::ReadAccountDirectoryRequest* request, ::data_service::AccountDirectoryResponse* response);
    virtual ::grpc::Status CreateAccountRole(::grpc::ServerContext* context, const ::data_service::CreateAccountRoleRequest* request, ::data_service::AccountDirectoryResponse* response);
    virtual ::grpc::Status LookupAccountRole(::grpc::ServerContext* context, const ::data_service::LookupAccountRoleRequest* request, ::data_service::AccountRoleOwnership* response);
    virtual ::grpc::Status RepairAccountRole(::grpc::ServerContext* context, const ::data_service::RepairAccountRoleRequest* request, ::data_service::AccountDirectoryResponse* response);
    virtual ::grpc::Status RemoveAccountRoles(::grpc::ServerContext* context, const ::data_service::RemoveAccountRolesRequest* request, ::google::protobuf::Empty* response);
    // 角色寄售控制仅允许独立 trade 证明；Begin 只阻新入场，不等于在线实体已冻结。
    virtual ::grpc::Status BeginAccountRoleTrade(::grpc::ServerContext* context, const ::data_service::BeginAccountRoleTradeRequest* request, ::data_service::AccountRoleTradeReceipt* response);
    // 请求不接受 caller proof。只有装配的服务端 SQL 验证器能确认 FROZEN；未装配时拒绝。
    virtual ::grpc::Status ConfirmAccountRoleTradeFreeze(::grpc::ServerContext* context, const ::data_service::ConfirmAccountRoleTradeFreezeRequest* request, ::data_service::AccountRoleTradeReceipt* response);
    virtual ::grpc::Status CancelAccountRoleTrade(::grpc::ServerContext* context, const ::data_service::CancelAccountRoleTradeRequest* request, ::data_service::AccountRoleTradeReceipt* response);
    virtual ::grpc::Status TransferAccountRole(::grpc::ServerContext* context, const ::data_service::TransferAccountRoleRequest* request, ::data_service::AccountRoleTransferReceipt* response);
    // scene 专用强鉴权；SQL 未登记前禁止实体复用、异步加载完成和激活。
    virtual ::grpc::Status RegisterRoleAdmission(::grpc::ServerContext* context, const ::data_service::RegisterRoleAdmissionRequest* request, ::data_service::RegisterRoleAdmissionResponse* response);
    // 只在本实例 <= through 的全部实体与迟到回调都已结束后关闭；无 TTL 自动关闭。
    virtual ::grpc::Status CloseRoleAdmissions(::grpc::ServerContext* context, const ::data_service::CloseRoleAdmissionsRequest* request, ::data_service::CloseRoleAdmissionsResponse* response);
    // 原 listing 的本地墓碑与排空 ACK；不是 caller 自报的冻结完成证明。
    virtual ::grpc::Status AckRoleTradeDrain(::grpc::ServerContext* context, const ::data_service::AckRoleTradeDrainRequest* request, ::google::protobuf::Empty* response);
    // ── Player lifecycle data ─────────────────────────────────────
    virtual ::grpc::Status LoadPlayerData(::grpc::ServerContext* context, const ::data_service::LoadPlayerDataRequest* request, ::data_service::LoadPlayerDataResponse* response);
    virtual ::grpc::Status SavePlayerData(::grpc::ServerContext* context, const ::data_service::SavePlayerDataRequest* request, ::data_service::SavePlayerDataResponse* response);
    // ── Fine-grained key/value access ────────────────────────────
    virtual ::grpc::Status GetPlayerField(::grpc::ServerContext* context, const ::data_service::GetPlayerFieldRequest* request, ::data_service::GetPlayerFieldResponse* response);
    virtual ::grpc::Status SetPlayerField(::grpc::ServerContext* context, const ::data_service::SetPlayerFieldRequest* request, ::data_service::SetPlayerFieldResponse* response);
    // ── Player-zone mapping (registration / merge) ───────────────
    virtual ::grpc::Status RegisterPlayerZone(::grpc::ServerContext* context, const ::data_service::RegisterPlayerZoneRequest* request, ::google::protobuf::Empty* response);
    virtual ::grpc::Status GetPlayerHomeZone(::grpc::ServerContext* context, const ::data_service::GetPlayerHomeZoneRequest* request, ::data_service::GetPlayerHomeZoneResponse* response);
    virtual ::grpc::Status BatchGetPlayerHomeZone(::grpc::ServerContext* context, const ::data_service::BatchGetPlayerHomeZoneRequest* request, ::data_service::BatchGetPlayerHomeZoneResponse* response);
    // Remap every player:zone:* mapping that points at source_zone_id to target_zone_id (server merge).
    virtual ::grpc::Status RemapHomeZoneForMerge(::grpc::ServerContext* context, const ::data_service::RemapHomeZoneForMergeRequest* request, ::data_service::RemapHomeZoneForMergeResponse* response);
    // ── Cleanup / merge ──────────────────────────────────────────
    virtual ::grpc::Status DeletePlayerData(::grpc::ServerContext* context, const ::data_service::DeletePlayerDataRequest* request, ::data_service::DeletePlayerDataResponse* response);
    // ── Snapshot / Rollback ──────────────────────────────────────
    virtual ::grpc::Status CreatePlayerSnapshot(::grpc::ServerContext* context, const ::data_service::CreatePlayerSnapshotRequest* request, ::data_service::CreatePlayerSnapshotResponse* response);
    virtual ::grpc::Status ListPlayerSnapshots(::grpc::ServerContext* context, const ::data_service::ListPlayerSnapshotsRequest* request, ::data_service::ListPlayerSnapshotsResponse* response);
    virtual ::grpc::Status GetPlayerSnapshotDiff(::grpc::ServerContext* context, const ::data_service::GetPlayerSnapshotDiffRequest* request, ::data_service::GetPlayerSnapshotDiffResponse* response);
    virtual ::grpc::Status RollbackPlayer(::grpc::ServerContext* context, const ::data_service::RollbackPlayerRequest* request, ::data_service::RollbackPlayerResponse* response);
    virtual ::grpc::Status RollbackZone(::grpc::ServerContext* context, const ::data_service::RollbackZoneRequest* request, ::data_service::RollbackZoneResponse* response);
    virtual ::grpc::Status RollbackAll(::grpc::ServerContext* context, const ::data_service::RollbackAllRequest* request, ::data_service::RollbackAllResponse* response);
    // ── Batch Recall / Anomaly / Event Snapshot ──────────────────
    virtual ::grpc::Status BatchRecallItems(::grpc::ServerContext* context, const ::data_service::BatchRecallItemsRequest* request, ::data_service::BatchRecallItemsResponse* response);
    virtual ::grpc::Status QueryTransactionLog(::grpc::ServerContext* context, const ::data_service::QueryTransactionLogRequest* request, ::data_service::QueryTransactionLogResponse* response);
    virtual ::grpc::Status CreateEventSnapshot(::grpc::ServerContext* context, const ::data_service::CreateEventSnapshotRequest* request, ::data_service::CreateEventSnapshotResponse* response);
    // ── ID segment allocation (Leaf-segment) ────────────────────
    // C++ scene 没有 MySQL 客户端,永久 ID(item guid 等)的号段经这里从 id_segment 表领取。
    // 见 docs/design/node-id-overhaul-plan-20260908.md §6。
    virtual ::grpc::Status AllocateIdSegment(::grpc::ServerContext* context, const ::data_service::AllocateIdSegmentRequest* request, ::data_service::AllocateIdSegmentResponse* response);
    // ── Player name registry(角色名全服唯一)──────────────────────
    // 真源是全局库 player_name 表(rollback_database_table.proto);zone 库
    // player_database.profile_component 与 AccountSimplePlayer.name 都只是副本。
    // 唯一性只有"全服一张表"才成立,所以登记必须过 data_service,不能各 zone 自己判重。
    // 设计见 docs/design/guild-phase2/03-names.md §3.1。
    virtual ::grpc::Status ReservePlayerName(::grpc::ServerContext* context, const ::data_service::ReservePlayerNameRequest* request, ::data_service::ReservePlayerNameResponse* response);
    virtual ::grpc::Status ReleasePlayerName(::grpc::ServerContext* context, const ::data_service::ReleasePlayerNameRequest* request, ::google::protobuf::Empty* response);
    virtual ::grpc::Status BatchGetPlayerName(::grpc::ServerContext* context, const ::data_service::BatchGetPlayerNameRequest* request, ::data_service::BatchGetPlayerNameResponse* response);
    // ── 资产通道:已落盘账本只读 ─────────────────────────────────
    // 读 zone Redis 里 scene 写的 PlayerAllData blob 的 asset_op_ledger 子字段。只读、不鉴权(与
    // BatchGetPlayerName 同级)。实现 go/shared/assetop 的 LedgerReader。
    // 设计见 docs/design/guild-phase2/07-rollback-fail-closed.md §7.8。
    virtual ::grpc::Status GetPlayerAssetOpLedger(::grpc::ServerContext* context, const ::data_service::GetPlayerAssetOpLedgerRequest* request, ::data_service::GetPlayerAssetOpLedgerResponse* response);
    // ── 玩家收件箱:已落盘账本只读 ───────────────────────────────
    // 读同一份 PlayerAllData blob 的 inbox_ledger 子字段,读法与错误语义照 GetPlayerAssetOpLedger。
    // 调用方是 go/player_inbox 的对账(定时作业与运维 ReconcilePlayer),不是 scene。
    // 设计见 docs/design/player-inbox-service.md §5.1、§9.3。
    virtual ::grpc::Status GetPlayerInboxLedger(::grpc::ServerContext* context, const ::data_service::GetPlayerInboxLedgerRequest* request, ::data_service::GetPlayerInboxLedgerResponse* response);
  };
